K.Guide = { ["id"] = true, ["updated"] = true, ["title"] = true, ["category"] = true, ["author"] = true, ["tags"] = true, ["levels"] = true, ["cond"] = true, ["source"] = true, ["materials"] = true, ["data"] = true }
function W.Guide(w, v, at)
    isTable(v, at, "a table")
    for key in pairs(v) do if not K.Guide[key] then fail(at, key, "is not a field here") end end
    local bits, x = 0, nil
    if v["id"] ~= nil then bits = bits + 1 end
    if v["updated"] ~= nil then bits = bits + 2 end
    if v["title"] ~= nil then bits = bits + 4 end
    if v["category"] ~= nil then bits = bits + 8 end
    if v["author"] ~= nil then bits = bits + 16 end
    if v["tags"] ~= nil then bits = bits + 32 end
    if v["levels"] ~= nil then bits = bits + 64 end
    if v["cond"] ~= nil then bits = bits + 128 end
    if v["source"] ~= nil then bits = bits + 256 end
    if v["materials"] ~= nil then bits = bits + 512 end
    if v["data"] ~= nil then bits = bits + 1024 end
    w:U(bits)
    x = v["id"] if x ~= nil then putS(w, x, at, "id") end
    x = v["updated"] if x ~= nil then putU(w, x, at, "updated") end
    x = v["title"] if x ~= nil then putS(w, x, at, "title") end
    x = v["category"] if x ~= nil then putS(w, x, at, "category") end
    x = v["author"] if x ~= nil then putS(w, x, at, "author") end
    x = v["tags"] if x ~= nil then W.Guide_tags(w, x, down(at, "tags")) end
    x = v["levels"] if x ~= nil then W.Guide_levels(w, x, down(at, "levels")) end
    x = v["cond"] if x ~= nil then W.Cond(w, x, down(at, "cond")) end
    x = v["source"] if x ~= nil then putS(w, x, at, "source") end
    x = v["materials"] if x ~= nil then putS(w, x, at, "materials") end
    x = v["data"] if x ~= nil then W.Guide_data(w, x, down(at, "data")) end
end
function R.Guide(r)
    local v, bits, b = {}, r:U(), 0
    if bits >= 2048 then r:Fail() return v end
    b = bits % 2 bits = (bits - b) / 2 if b == 1 then v["id"] = r:Bytes() end
    b = bits % 2 bits = (bits - b) / 2 if b == 1 then v["updated"] = r:U() end
    b = bits % 2 bits = (bits - b) / 2 if b == 1 then v["title"] = r:Bytes() end
    b = bits % 2 bits = (bits - b) / 2 if b == 1 then v["category"] = r:Bytes() end
    b = bits % 2 bits = (bits - b) / 2 if b == 1 then v["author"] = r:Bytes() end
    b = bits % 2 bits = (bits - b) / 2 if b == 1 then v["tags"] = R.Guide_tags(r) end
    b = bits % 2 bits = (bits - b) / 2 if b == 1 then v["levels"] = R.Guide_levels(r) end
    b = bits % 2 bits = (bits - b) / 2 if b == 1 then v["cond"] = R.Cond(r) end
    b = bits % 2 bits = (bits - b) / 2 if b == 1 then v["source"] = r:Bytes() end
    b = bits % 2 bits = (bits - b) / 2 if b == 1 then v["materials"] = r:Bytes() end
    b = bits % 2 bits = (bits - b) / 2 if b == 1 then v["data"] = R.Guide_data(r) end
    return v
end
