function M.Encode(value)
    local w = ns.Kit.Codec.Writer()
    local ok, err = pcall(function() W.Guide(w, value, 0) end)
    if ok then return w:Finish() end
    if type(err) == "table" and err.codecMessage then
        local path = where(err.codecPath)
        return nil, (path ~= "" and path .. " " or "") .. err.codecMessage
    end
    return nil, tostring(err)
end

function M.Decode(bytes)
    if type(bytes) ~= "string" then return nil, "there is nothing to read" end
    local r = ns.Kit.Codec.Reader(bytes)
    local value = R.Guide(r)
    if not r:Ok() then return nil, "it is damaged" end
    if r:More() then return nil, "it has bytes left over" end
    return value
end

ns:RegisterModule("GuideCodec", M)
